    commit_by_hash = {}
    for idx, line in enumerate(lines):
        p = line.split('|')
        c = {
            'hash': p[0], 'parents': p[1].split() if p[1] else [],
            'refs': p[2], 'msg': p[3], 'time': int(p[4]),
            'short': p[5], 'idx': idx
        }
        commits.append(c)
        commit_by_hash[c['hash']] = c

    heads = []
    for c in commits:
        if c['refs']:
            for ref in c['refs'].split(','):
                ref = ref.strip()
                if ref.startswith('HEAD -> '): ref = ref[8:]
                if ref == 'HEAD': continue
                heads.append({'hash': c['hash'], 'name': ref, 'time': c['time']})
        if len(c['parents']) > 1:
            for p in c['parents'][1:]:
                name = 'unknown'
                m = re.search(r"Merge branch '([^']+)'", c['msg'])
                if m: name = m.group(1)
                else:
                    m = re.search(r"Merge pull request #\d+ from [^/]+/([^ ]+)", c['msg'])
                    if m: name = "fork/" + m.group(1)
                heads.append({'hash': p, 'name': name, 'time': commit_by_hash[p]['time'] if p in commit_by_hash else c['time']})

    for h in heads:
        h['pers'] = get_persistence(h['name'], model)
        h['ord'] = get_order_group(h['name'], model)

    heads.sort(key=lambda x: (x['pers'], -x['time']))

    class Branch:
        def __init__(self, bid, name, hhash, pers, ord_g):
            self.id = bid; self.name = name; self.head_hash = hhash
            self.pers = pers; self.ord = ord_g; self.commits = []

    branches = []
    assigned = {}
    for h in heads:
        hhash = h['hash']
        if hhash not in commit_by_hash: continue
        if hhash not in assigned:
            b = Branch(len(branches), h['name'], hhash, h['pers'], h['ord'])
            branches.append(b)
            curr = hhash
            while curr and curr not in assigned:
                assigned[curr] = b.id
                b.commits.append(curr)
                parents = commit_by_hash[curr]['parents']
                curr = parents[0] if parents else None

    branches = [b for b in branches if b.commits]

    for b in branches:
        b.start_idx = min(commit_by_hash[c]['idx'] for c in b.commits)
        last_c = commit_by_hash[b.commits[-1]]
        p = last_c['parents'][0] if last_c['parents'] else None
        if p and p in commit_by_hash:
            b.end_idx = commit_by_hash[p]['idx']
            p_bid = assigned.get(p, 0)
            b.source_group = branches[p_bid].ord if p_bid < len(branches) else 0
        else:
            b.end_idx = max(commit_by_hash[c]['idx'] for c in b.commits)
            b.source_group = 0

        target = None
        for c in commits:
            if b.head_hash in c['parents'][1:]:
                target = c
                break
        if target:
            t_bid = assigned.get(target['hash'], 0)
            b.target_group = branches[t_bid].ord if t_bid < len(branches) else 0
        else:
            b.target_group = 0

    branches_sort = sorted(branches, key=lambda b: (max(b.source_group, b.target_group), b.end_idx - b.start_idx, -b.start_idx))

    base_col = 0
    for og in range(4):
        g_branches = [b for b in branches_sort if b.ord == og]
        if not g_branches: continue
        occupied = []
        for b in g_branches:
            col = 0
            while True:
                if col >= len(occupied):
                    occupied.append([])
                    break
                overlap = False
                for s, e in occupied[col]:
                    if max(s, b.start_idx) <= min(e, b.end_idx):
                        overlap = True
                        break
                if not overlap: break
                col += 1
            b.col = base_col + col
            occupied[col].append((b.start_idx, b.end_idx))
        base_col += len(occupied)

    col_map = {b.id: b.col for b in branches}

    # Rendering
    targets = {}
    for c in commits:
        chash = c['hash']
        c_col = col_map.get(assigned.get(chash, 0), 0)

        needs_gap = []
        for col, tset in targets.items():
            if chash in tset and col != c_col:
                needs_gap.append(col)

        if needs_gap:
            row = [' ']*(base_col*2 + 2)
            all_cols = needs_gap + [c_col]
            min_c, max_c = min(all_cols), max(all_cols)
            for i in range(min_c*2 + 1, max_c*2 + 1):
                row[i] = '─'
            for col in needs_gap:
                targets[col].remove(chash)
                if not targets[col]:
                    row[col*2 + 1] = '┘' if col > c_col else '└'
                else:
                    row[col*2 + 1] = '┤' if col > c_col else '├'

            # draw c_col connection correctly!
            # if c_col is min_c, it branches off to the right, so it's ├
            # if c_col is max_c, it branches off to the left, so it's ┤
            # if c_col is in the middle, it's ┴
            if c_col == min_c: row[c_col*2 + 1] = '├'
            elif c_col == max_c: row[c_col*2 + 1] = '┤'
            else: row[c_col*2 + 1] = '┴'

            # Also draw lines for active targets passing through
            for col, tset in targets.items():
                if tset and col not in all_cols and min_c < col < max_c:
                    row[col*2 + 1] = '┼'
                elif tset and col not in all_cols:
                    if len(row) <= col*2 + 1: row.extend([' ']*(col*2 + 2 - len(row)))
                    row[col*2 + 1] = '│'

            print(" " + "".join(row).rstrip())

        row = [' ']*(base_col*2 + 2)

        if len(c['parents']) > 1:
            row[c_col*2 + 1] = '○'
        else:
            row[c_col*2 + 1] = '●'

        merged_cols = []
        if len(c['parents']) > 1:
            for p in c['parents'][1:]:
                if p in commit_by_hash:
                    p_col = col_map.get(assigned.get(p, 0), 0)
                    merged_cols.append(p_col)
                    if p_col not in targets: targets[p_col] = set()
                    targets[p_col].add(p)

        for mc in merged_cols:
            if mc == c_col: continue
            min_m, max_m = min(c_col, mc), max(c_col, mc)
            for i in range(min_m*2 + 2, max_m*2 + 1):
                if row[i] == '│': row[i] = '┼'
                else: row[i] = '─'
            row[mc*2 + 1] = '┐' if mc > c_col else '┌'
            if mc > c_col:
                row[c_col*2 + 2] = '<'
            else:
                row[c_col*2] = '>'

        for col, tset in targets.items():
            if tset and col != c_col and (len(row) <= col*2 + 1 or row[col*2 + 1] == ' '):
                if len(row) <= col*2 + 1: row.extend([' ']*(col*2 + 2 - len(row)))
                row[col*2 + 1] = '│'

        if c['parents']:
            p0 = c['parents'][0]
            if p0 in commit_by_hash:
                if c_col not in targets: targets[c_col] = set()
                targets[c_col].add(p0)

        if chash in targets.get(c_col, set()):
            targets[c_col].remove(chash)

        refs_str = f" ({c['refs']})" if c['refs'] else ""
        print(" " + "".join(row).rstrip() + f"  {c['short']}{refs_str} {c['msg']}")

if __name__ == '__main__':
    main()
